// 500ms 查詢完成後，才在同一把鎖內重新讀取、判斷、寫入；鎖內無 await，只有 transitioned 的那一次會排入通知。
store.TryCancel(id, out var current, out var result, out var transitioned);
string outcome; int status;
if (current.Shipped) { outcome = "rejected_shipped"; status = 409; }         // BR-02，不通知（NC-03）
else if (transitioned) { outcome = "ok"; status = 200; }

public bool TryGet(string id, out Order o) { lock (_g) return _d.TryGetValue(id, out o!); }
// 讀取、判斷、寫入在同一把鎖內完成，同一訂單只會有一次 transitioned=true。呼叫前訂單已確認存在（本服務不刪單）。
public void TryCancel(string id, out Order current, out CancellationResult result, out bool transitioned)
{
    lock (_g)
    {
        current = _d[id];
        result = Cancellation.Cancel(current);
        transitioned = Cancellation.Transitioned(current, result);
        if (transitioned) _d[id] = result.Order;
    }
}
